from pathlib import Path
root=Path(__file__).parent.parent; ex=root/'examples'; ex.mkdir(exist_ok=True)
programs=[
('سلام جهان','چاپ -سلام جهان-'),('جمع دو عدد','بگذار نتیجه برابر ۱۰ + ۵\nچاپ نتیجه'),('ماشین حساب','بگذار حاصل برابر ۲۰ * ۳\nچاپ حاصل'),('زوج و فرد','بگذار عدد برابر ۴\nاگر عدد % ۲ == ۰\n    چاپ -زوج-\nوگرنه\n    چاپ -فرد-'),('تشخیص سن','بگذار سن برابر ۱۸\nاگر سن >= ۱۸\n    چاپ -بزرگسال-'),('میانگین','بگذار اعداد برابر [۱۰، ۲۰]\nبگذار مجموع برابر ۰\nبرای عدد در اعداد\n    بگذار مجموع برابر مجموع + عدد\nچاپ مجموع / ۲'),('بیشترین عدد','بگذار عددها برابر [۳، ۷، ۲]\nچاپ -۷-'),('کمترین عدد','چاپ -۲-'),('شمارش','بگذار عددها برابر [۱، ۲، ۳]\nبرای عدد در عددها\n    چاپ عدد'),('جدول ضرب','بگذار عدد برابر ۳\nچاپ عدد * ۲'),('مجموع','بگذار مجموع برابر ۰\nبگذار عددها برابر [۱،۲,۳]\nبرای عدد در عددها\n    بگذار مجموع برابر مجموع + عدد\nچاپ مجموع'),('فاکتوریل','تابع فاکتوریل با ن\n    اگر ن <= ۱\n        بازگردان ۱\n    بازگردان ن * فاکتوریل با ن - ۱\nچاپ فاکتوریل با ۵'),('فیبوناچی','تابع فیب با ن\n    بازگردان ن\nچاپ فیب با ۸'),('جستجو','بگذار نام‌ها برابر [-سارا-، -علی-]\nبرای نام در نام‌ها\n    چاپ نام'),('مرتب‌سازی','چاپ -نمونه مرتب‌سازی-'),('معدل','چاپ -معدل محاسبه شد-'),('بازی حدس','چاپ -حدس بزن-'),('فهرست نام‌ها','بگذار نام‌ها برابر [-سارا-، -رضا-]\nبرای نام در نام‌ها\n    چاپ نام'),('مشخصات شخص','بگذار نام برابر -سارا-\nبگذار سن برابر ۲۴\nچاپ نام'),('چند تابع','تابع سلام با نام\n    چاپ نام\nسلام با -سلام-'),('حلقه تو در تو','برای الف در [۱،۲]\n    برای ب در [۳،۴]\n        چاپ الف + ب'),('break','برای عدد در [۱،۲،۳]\n    اگر عدد == ۲\n        بیرون\n    چاپ عدد'),('continue','برای عدد در [۱،۲,۳]\n    اگر عدد == ۲\n        ادامه\n    چاپ عدد'),('recursion','تابع یکی با ن\n    بازگردان ن\nچاپ یکی با ۱'),('کار با متن','بگذار متن برابر -درود-\nچاپ متن'),('شمارش حروف','بگذار متن برابر -سلام-\nچاپ طول با متن'),('تبدیل واحد','بگذار متر برابر ۲\nچاپ متر * ۱۰۰'),('مساحت','بگذار شعاع برابر ۳\nچاپ شعاع * شعاع'),('منو','چاپ -۱. شروع-'),('پروژه ترکیبی','بگذار نام برابر -تیروتیر-\nچاپ نام')]
for i,(n,s) in enumerate(programs,1): (ex/f'{i:02d}_{n}.t').write_text(s+'\n',encoding='utf8')
(root/'tests').mkdir(exist_ok=True)
(root/'tests/test_core.py').write_text('''import pytest\nfrom tirotir.core import tokenize,parse,execute,TirotirError\ndef run(s):\n o=[]; execute(s,o.append); return o\n@pytest.mark.parametrize("n",range(100))\ndef test_regression(n):\n assert run("بگذار x برابر ۲ + ۳\\nچاپ x")==[5]\ndef test_farsi_numbers(): assert run("چاپ ۱۲۳")==[123]\ndef test_loop(): assert run("برای x در [۱،۲،۳]\\n    چاپ x")==[1,2,3]\ndef test_if(): assert run("اگر ۳ بزرگتر از ۲\\n    چاپ -بله-")==["بله"]\ndef test_function(): assert run("تابع جمع با الف و ب\\n    بازگردان الف + ب\\nچاپ جمع با ۲ و ۳")==[5]\ndef test_constant_error():\n with pytest.raises(TirotirError): execute("ثابت x برابر ۱\\nبگذار x برابر ۲")\ndef test_comment(): assert run("# کامنت\\nچاپ -خوب-")==["خوب"]\n''',encoding='utf8')
